class ContentType {
  #valid = true
  #empty = true
  #type = ''
  #subtype = ''
  #parameters = new Map()

  constructor (headerValue) {
    if (headerValue == null || headerValue === '' || headerValue === 'undefined') {
      return
    }
    this.#parse(String(headerValue))
  }

  #parse (header) {
    const len = header.length
    let pos = 0
    while (pos < len && isOWS(header.charCodeAt(pos))) pos++

    let end = pos
    while (end < len && header.charCodeAt(end) !== 59 && !isOWS(header.charCodeAt(end))) end++

    const essence = header.slice(pos, end)
    const slash = essence.indexOf('/')
    if (slash < 1 || slash === essence.length - 1) {
      this.#valid = false
      return
    }
    const type = essence.slice(0, slash)
    const subtype = essence.slice(slash + 1)
    if (!tokenRE.test(type) || !tokenRE.test(subtype)) {
      this.#valid = false
      return
    }

    pos = end
    while (pos < len && isOWS(header.charCodeAt(pos))) pos++
    if (pos < len && header.charCodeAt(pos) !== 59) {
      this.#valid = false
      return
    }

    this.#type = type.toLowerCase()
    this.#subtype = subtype.toLowerCase()
    this.#empty = false

    // parameters
    while (pos < len) {
      pos++ // skip ';'
      while (pos < len && isOWS(header.charCodeAt(pos))) pos++
      if (pos >= len) break

      let nameEnd = pos
      while (nameEnd < len && header.charCodeAt(nameEnd) !== 61 && header.charCodeAt(nameEnd) !== 59) nameEnd++
      const name = header.slice(pos, nameEnd).trim().toLowerCase()
      if (nameEnd >= len || header.charCodeAt(nameEnd) === 59 || !tokenRE.test(name)) {
        // malformed parameter, skip it
        pos = header.indexOf(';', nameEnd)
        if (pos === -1) break
        continue
      }
      pos = nameEnd + 1

      let value
      if (header.charCodeAt(pos) === 34) {
        pos++
        value = ''
        let closed = false
        while (pos < len) {
          const code = header.charCodeAt(pos)
          if (code === 92 && pos + 1 < len) {
            value += header[pos + 1]
            pos += 2
            continue
          }
          pos++
          if (code === 34) {
            closed = true
            break
          }
          value += header[pos - 1]
        }
        if (!closed) value = 'invalid quoted string'
      } else {
        let valueEnd = pos
        while (valueEnd < len && header.charCodeAt(valueEnd) !== 59) valueEnd++
        value = header.slice(pos, valueEnd).trim()
        pos = valueEnd
        if (!tokenRE.test(value)) {
          continue
        }
      }

      if (!this.#parameters.has(name)) this.#parameters.set(name, value)

      while (pos < len && isOWS(header.charCodeAt(pos))) pos++
      if (pos < len && header.charCodeAt(pos) !== 59) {
        const next = header.indexOf(';', pos)
        if (next === -1) break
        pos = next
      }
    }
  }

  get isEmpty () {
    return this.#empty
  }

  get isValid () {
    return this.#valid
  }

  get mediaType () {
    return this.#empty ? kEmptyMediaType : `${this.#type}/${this.#subtype}`
  }

  get type () {
    return this.#type
  }

  get subtype () {
    return this.#subtype
  }

  get parameters () {
    return this.#parameters
  }

  toString () {
    if (this.#empty) return kEmptyMediaType
    const parts = [this.mediaType]
    for (const [name, value] of this.#parameters) {
      parts.push(`${name}="${value.replace(/["\\]/g, '\\$&')}"`)
    }
    return parts.join('; ')
  }
}

